func:
// One message per reading of a "two AIs" region (task parts_check) from
// tesr_vision_runner.py --broker <this computer>. Each picture in a folder run
// is one reading; on a camera, a reading is sent when the verdict changes.
const r = msg.payload;
const v = r && typeof r === "object" ? r.value : null;
if (!v || typeof v !== "object" || !("result" in v)) return null;   // the picture, or another kind of region
if (v.result === "none") {
    node.status({fill: "grey", shape: "ring", text: "no object in view"});
    return null;
}
const c = flow.get("qc") || {ok: 0, ng: 0};
if (v.result === "OK") c.ok += 1; else c.ng += 1;
flow.set("qc", c);
const found = (v.found || []).join(" / ");
node.status({fill: v.result === "OK" ? "green" : "red", shape: "dot",
             text: "OK " + c.ok + " · NG " + c.ng + "   (last " + v.result + " " + found + " of " + v.expect + ")"});
msg.payload = {ok: c.ok, ng: c.ng, last: v.result, found: v.found, expect: v.expect,
               region: r.roi, camera: r.camera, time: r.time};
return msg;

flow.set("qc", {ok: 0, ng: 0});
node.status({fill: "grey", shape: "ring", text: "counts reset"});
return null;
